import { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import './profile.scss';

const Profile = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);
  const { id } = useParams();
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    username: '',
    name: '',
    bio: '',
    dob: '',
  });
  const [profilePictureFile, setProfilePictureFile] = useState(null);
  const [formError, setFormError] = useState(null);

  useEffect(() => {
    const fetchUser = async () => {
      setLoading(true);
      try {
        const res = await axios.get(`http://localhost:5000/api/users/${id}`, {
          headers: {
            Authorization: `Bearer ${localStorage.getItem('token')}`,
          },
        });
        setUser(res.data);
        setFormData({
          username: res.data.username,
          name: res.data.name,
          bio: res.data.bio || '',
          dob: res.data.dob ? res.data.dob.split('T')[0] : '',
        });
        setError(null);
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to load user');
      } finally {
        setLoading(false);
      }
    };

    fetchUser();
  }, [id]);

  const handleEditToggle = () => {
    setIsEditing(!isEditing);
    setFormError(null);
    setProfilePictureFile(null);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    console.log('Selected file:', file ? { name: file.name, size: file.size, type: file.type } : 'No file selected');
    if (file) {
      const ext = file.name.split('.').pop().toLowerCase();
      if (!['jpg', 'jpeg', 'png'].includes(ext)) {
        setFormError('Only .jpg, .jpeg, or .png files are allowed');
        return;
      }
      if (file.size > 5 * 1024 * 1024) {
        setFormError('File size exceeds 5MB limit');
        return;
      }
      setProfilePictureFile(file);
      setFormError(null);
    } else {
      setProfilePictureFile(null);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.username || !formData.name) {
      setFormError('Username and name are required');
      return;
    }

    const data = new FormData();
    data.append('username', formData.username);
    data.append('name', formData.name);
    data.append('bio', formData.bio);
    if (formData.dob) {
      data.append('dob', formData.dob);
    }
    if (profilePictureFile) {
      data.append('profilePicture', profilePictureFile);
    }
    console.log('FormData entries:', [...data.entries()]);

    try {
      console.log('Sending PUT request to:', `http://localhost:5000/api/users/${id}`);
      const res = await axios.put(`http://localhost:5000/api/users/${id}`, data, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
      });
      console.log('Update response:', res.data);
      setUser(res.data);
      setIsEditing(false);
      setFormError(null);
      setProfilePictureFile(null);
    } catch (err) {
      console.error('Update error:', err.response?.data || err.message);
      setFormError(err.response?.data?.message || 'Failed to update profile');
    }
  };

  if (!currentUser) {
    return null;
  }

  if (loading) {
    return <div className="profile">Loading...</div>;
  }

  if (error) {
    return <div className="profile error">{error}</div>;
  }

  const isOwnProfile = currentUser.id === id;
  const formattedDOB = user.dob ? new Date(user.dob).toLocaleDateString() : 'Not set';
  const formattedJoinDate = user.createdAt ? new Date(user.createdAt).toLocaleDateString() : 'Not set';
  const friendsCount = user.friends?.length || 0;

  // Construct full image URL
  const profilePictureUrl = user.profilePicture
    ? `http://localhost:5000${user.profilePicture}?t=${new Date().getTime()}`
    : '/default-avatar.png';

  return (
    <div className={`profile ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <h2>{user.name}'s Profile</h2>
      {isOwnProfile && (
        <button className="edit-btn" onClick={handleEditToggle}>
          {isEditing ? 'Cancel' : 'Edit Profile'}
        </button>
      )}
      {isEditing && isOwnProfile ? (
        <form className="edit-form" onSubmit={handleSubmit} encType="multipart/form-data">
          <div className="form-group">
            <label>Username</label>
            <input
              type="text"
              name="username"
              value={formData.username}
              onChange={handleInputChange}
              required
            />
          </div>
          <div className="form-group">
            <label>Name</label>
            <input
              type="text"
              name="name"
              value={formData.name}
              onChange={handleInputChange}
              required
            />
          </div>
          <div className="form-group">
            <label>Profile Picture</label>
            <input
              type="file"
              name="profilePicture"
              accept="image/jpeg,image/png"
              onChange={handleFileChange}
            />
            {profilePictureFile && (
              <img
                src={URL.createObjectURL(profilePictureFile)}
                alt="Preview"
                className="preview-img"
              />
            )}
          </div>
          <div className="form-group">
            <label>Bio</label>
            <textarea
              name="bio"
              value={formData.bio}
              onChange={handleInputChange}
              rows="4"
            />
          </div>
          <div className="form-group">
            <label>Date of Birth</label>
            <input
              type="date"
              name="dob"
              value={formData.dob}
              onChange={handleInputChange}
            />
          </div>
          {formError && <p className="form-error">{formError}</p>}
          <button type="submit" className="save-btn">Save Changes</button>
        </form>
      ) : (
        <div className="profile-details">
          <img src={profilePictureUrl} alt={user.name} className="avatar" onError={(e) => console.error('Image load error:', e)} />
          <div className="info">
            <p><strong>Username:</strong> {user.username}</p>
            <p><strong>Name:</strong> {user.name}</p>
            <p><strong>Friends:</strong> {friendsCount}</p>
            <p><strong>Bio:</strong> {user.bio || 'No bio set'}</p>
            <p><strong>Date of Birth:</strong> {formattedDOB}</p>
            <p><strong>Joined:</strong> {formattedJoinDate}</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default Profile;
